		/**
		 * Returns a new populated Item
		 * 
		 * @return Item
		 */
		protected Item generateNewEntity() {
			Item entity = new Item( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Money(),  new Measurement(),  new Boolean(true),  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  ItemType.values()[0],  ProcurementType.values()[0],  UnitOfMeasure.values()[0],  ProductLifecycleStatus.values()[0] );
			
			return( entity );
		}

